/bin/zsh -c "cat > schema.sql <<'EOF'
CREATE ROLE app LOGIN NOSUPERUSER NOINHERIT;
CREATE ROLE invoice_purge NOLOGIN NOSUPERUSER NOINHERIT;

CREATE TABLE accounts (id text PRIMARY KEY, is_demo boolean NOT NULL);
CREATE TABLE orders (id text PRIMARY KEY, account_id text NOT NULL REFERENCES accounts(id), state text NOT NULL DEFAULT 'NEW');
CREATE TABLE invoice_audit (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id) ON DELETE RESTRICT);

CREATE FUNCTION reject_audit_change() RETURNS trigger LANGUAGE plpgsql AS "'$$
BEGIN
  IF TG_OP = '"'DELETE' AND current_user = 'invoice_purge' THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'invoice audit is immutable';
END "'$$;
CREATE TRIGGER invoice_audit_immutable BEFORE UPDATE OR DELETE ON invoice_audit FOR EACH ROW EXECUTE FUNCTION reject_audit_change();
CREATE TRIGGER invoice_audit_no_truncate BEFORE TRUNCATE ON invoice_audit FOR EACH STATEMENT EXECUTE FUNCTION reject_audit_change();

CREATE FUNCTION complete_order(order_id text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO invoice_audit(order_id) VALUES (complete_order.order_id);
  UPDATE orders SET state = '"'DONE' WHERE id = complete_order.order_id;
END "'$$;

CREATE FUNCTION purge_demo_account(account_id text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  unhandled text;
BEGIN
  -- Every non-cascading child of a table deleted below must be handled here.
  SELECT string_agg(DISTINCT c.conrelid::regclass::text, '"', ' ORDER BY c.conrelid::regclass::text)
    INTO unhandled
    FROM pg_catalog.pg_constraint c
   WHERE c.contype = 'f' AND c.confdeltype IN ('a', 'r')
     AND c.confrelid IN ('public.accounts'::regclass, 'public.orders'::regclass, 'public.invoice_audit'::regclass)
     AND NOT (c.conrelid = ANY (ARRAY['public.orders'::regclass, 'public.invoice_audit'::regclass]));
  IF unhandled IS NOT NULL THEN
    RAISE EXCEPTION 'purge_demo_account has unhandled foreign key references from: %', unhandled USING ERRCODE = 'P0001';
  END IF;

  DELETE FROM public.invoice_audit a USING public.orders o, public.accounts ac
   WHERE a.order_id = o.id AND o.account_id = ac.id
     AND ac.id = purge_demo_account.account_id AND ac.is_demo;
  DELETE FROM public.orders o USING public.accounts ac
   WHERE o.account_id = ac.id AND ac.id = purge_demo_account.account_id AND ac.is_demo;
  DELETE FROM public.accounts ac WHERE ac.id = purge_demo_account.account_id AND ac.is_demo;
END "'$$;
GRANT USAGE ON SCHEMA public TO invoice_purge;
GRANT SELECT, DELETE ON accounts, orders, invoice_audit TO invoice_purge;
ALTER FUNCTION purge_demo_account(text) OWNER TO invoice_purge;
REVOKE ALL ON FUNCTION purge_demo_account(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION purge_demo_account(text) TO app;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO app;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO app;
EOF
cat > test.sql <<'"'EOF'
\\set ON_ERROR_STOP on
INSERT INTO accounts VALUES ('demo', true), ('real', false);
INSERT INTO orders(id, account_id) VALUES ('demo-order', 'demo'), ('real-order', 'real');
SET ROLE app;
SELECT complete_order('demo-order');
SELECT complete_order('real-order');
SET app.purge = 'on';
DO "'$$ BEGIN
  BEGIN DELETE FROM invoice_audit; RAISE EXCEPTION '"'delete unexpectedly succeeded';
  EXCEPTION WHEN raise_exception THEN IF SQLERRM = 'delete unexpectedly succeeded' THEN RAISE; END IF; END;
  BEGIN UPDATE invoice_audit SET order_id = order_id; RAISE EXCEPTION 'update unexpectedly succeeded';
  EXCEPTION WHEN raise_exception THEN IF SQLERRM = 'update unexpectedly succeeded' THEN RAISE; END IF; END;
  BEGIN TRUNCATE invoice_audit; RAISE EXCEPTION 'truncate unexpectedly succeeded';
  EXCEPTION WHEN insufficient_privilege THEN NULL; WHEN raise_exception THEN IF SQLERRM = 'truncate unexpectedly succeeded' THEN RAISE; END IF; END;
END "'$$;
SELECT purge_demo_account('"'real');
SELECT purge_demo_account('demo');
DO "'$$ BEGIN
  IF EXISTS (SELECT FROM accounts WHERE id = '"'demo') OR EXISTS (SELECT FROM orders WHERE id = 'demo-order') OR EXISTS (SELECT FROM invoice_audit WHERE order_id = 'demo-order') THEN RAISE EXCEPTION 'demo data remains'; END IF;
  IF NOT EXISTS (SELECT FROM accounts WHERE id = 'real') OR NOT EXISTS (SELECT FROM orders WHERE id = 'real' AND state = 'DONE') OR NOT EXISTS (SELECT FROM invoice_audit WHERE order_id = 'real-order') THEN RAISE EXCEPTION 'real data lost'; END IF;
END "'$$;
RESET ROLE;
CREATE TABLE new_reference (id int, order_id text REFERENCES orders(id));
SET ROLE app;
DO $$ BEGIN
  BEGIN PERFORM purge_demo_account('"'real'); RAISE EXCEPTION 'missing reference was not diagnosed';
  EXCEPTION WHEN raise_exception THEN IF SQLERRM NOT LIKE '%new_reference%' THEN RAISE; END IF; END;
END "'$$;
RESET ROLE;
-- Exercise the statement trigger even for a role with TRUNCATE privilege.
DO $$ BEGIN
  BEGIN TRUNCATE invoice_audit; RAISE EXCEPTION '"'truncate unexpectedly succeeded';
  EXCEPTION WHEN raise_exception THEN IF SQLERRM = 'truncate unexpectedly succeeded' THEN RAISE; END IF; END;
END "'$$;
EOF
container_id=$(docker run -d --rm -e POSTGRES_PASSWORD=test postgres:18-alpine) && for i in {1..30}; do docker exec "$container_id" pg_isready -U postgres >/dev/null 2>&1 && break; sleep 1; done && docker exec -i "$container_id" psql -U postgres -v ON_ERROR_STOP=1 < schema.sql && docker exec -i "$container_id" psql -U postgres -v ON_ERROR_STOP=1 < test.sql; result=$?; docker stop "$container_id" >/dev/null; exit $result'

